def main():
 ref=json.loads(zlib.decompress(base64.b85decode(DATA)).decode())
 out=pathlib.Path('salida_109');out.mkdir(exist_ok=True)
 summary={'version':'1.09','fecha_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'fuente':'Artefactos historicos GitHub 1.07 y 1.08 incrustados; sin red','motor_validado':False,'catalogo_validado':False,'publicable':False,'historico_modificado':False,'anios':{},'advertencias':['Los registros de pedrea y filas PDF proceden de la 1.07, no de una nueva extraccion independiente','La conciliacion del JSON solo abarca los 13 premios mayores por sorteo','Las reglas de acumulacion del resto de numeros siguen pendientes de comprobacion independiente','No usar estos importes para informar premios reales']}
 for year in (2024,2025):
  y=str(year); entries=ref[f'componentes_navidad_{year}_107.json']; previous=ref[f'auditoria_economica_navidad_{year}_107.json']; major=ref[f'contraste_premios_mayores_navidad_{year}_108.json'];
  print('Procesando',year,flush=True)
  print('Campos referencia',list(major)[:12],flush=True)
  # El informe de la 1.08 contiene los 13 importes y sus pruebas de extraccion
  major_rows=major.get('premios',major.get('comparaciones',major.get('resultados',[])))
  if not major_rows:
   for k,v in major.items():
    if isinstance(v,list) and len(v)==13 and isinstance(v[0],dict):major_rows=v;break
  if len(major_rows)!=13:raise ValueError('No se hallan 13 registros de premios principales 1.08: '+str(list(major)))
  major_map={str(r.get('numero','')).zfill(5):r for r in major_rows}
  if len(major_map)!=13:raise ValueError('Premios principales duplicados')
  originals={r['numero']:r for r in entries};
  if len(originals)!=len(entries):raise ValueError('Numeros duplicados en referencia 1.07')
  detail=[];differences=[]; category_counts=collections.Counter(); overlaps=collections.Counter();main_check=[]
  for i in range(100000):
   num=f'{i:05d}';old=originals.get(num,{'componentes':[]});comps=old['componentes']; base=[]; extras=[]
   for c in comps:
    if c['categoria'] in ('primerPremio','segundoPremio','tercerosPremios','cuartosPremios','quintosPremios'):
     base.append(c)
    else:extras.append(c)
   if len(base)>1:raise ValueError('Premios principales duplicados '+num)
   if num in major_map:
    m=major_map[num];pdfval=m['bloques_pdf'][0]['euros_decimo_pdf'] if len(m.get('bloques_pdf',[]))==1 else None
    jsonval=m.get('euros_decimo_json')
    if pdfval is None or jsonval is None:
     # Otros esquemas del registro se gestionan explicitamente tras inspeccion
     raise ValueError('Esquema 1.08 desconocido: '+str(m)[:600])
    if len(base)!=1:raise ValueError('Premio mayor no encontrado en componentes '+num)
    amount=round(float(pdfval)*100)
    expected=round(float(jsonval)*100)
    if round(float(base[0]['euros_decimo'])*100)!=expected:raise ValueError('Desacuerdo 1.07/1.08 '+num)
   else:
    if base:raise ValueError('Premio principal ausente 1.08 '+num)
    amount=0;expected=None
   extra_cents=sum(round(float(c['euros_decimo'])*100) for c in extras)
   total=amount+extra_cents
   cats=[c['categoria'] for c in extras]+[c['categoria'] for c in base]
   for c in cats:category_counts[c]+=1
   if len(cats)>1:overlaps['con_varias_categorias']+=1
   if len(cats)!=len(set(cats)):overlaps['categorias_repetidas_en_mismo_numero']+=1
   if base:
    # Para contrastar el JSON solo sumamos el reintegro, pues otros premios pueden
    # no estar incorporados en ese JSON de premios mayores.
    reintegro=sum(round(float(c['euros_decimo'])*100) for c in extras if c['categoria']=='reintegro')
    json_reintegro_esperado=amount+reintegro
    delta=expected-json_reintegro_esperado
    check={'numero':num,'premio_base_pdf_euros':amount/100,'reintegro_euros':reintegro/100,'json_euros':expected/100,'pdf_mas_reintegro_euros':json_reintegro_esperado/100,'diferencia_json_menos_pdf_y_reintegro_euros':delta/100,'otros_componentes_euros':(extra_cents-reintegro)/100,'coincide':delta==0}
    main_check.append(check)
    if delta: differences.append(check)
   if cats:
    detail.append({'numero':num,'importe_experimental_euros_decimo':total/100,'premio_mayor_base_pdf_euros':amount/100,'componentes_adicionales':extras,'categorias':cats,'requiere_validacion':True})
  if len(main_check)!=13:raise ValueError('No se contrastaron 13 premios principales')
  oldtotal=round(float(previous['suma_experimental_por_decimo_de_todos_los_numeros_euros'])*100)
  newtotal=sum(round(r['importe_experimental_euros_decimo']*100) for r in detail)
  report={'anio':year,'universo_numeros':100000,'numeros_con_componentes':len(detail),'premios_mayores_contrastados':len(main_check),'premios_mayores_pdf_mas_reintegro_coinciden_json':sum(r['coincide'] for r in main_check),'premios_mayores_discrepantes':differences,'suma_experimental_anterior_euros':oldtotal/100,'suma_experimental_corregida_euros':newtotal/100,'diferencia_suma_euros':(newtotal-oldtotal)/100,'recuentos_categorias':dict(category_counts),'solapamientos':dict(overlaps),'validacion_independiente_todos_los_premios':False,'publicable':False,'detalle_contraste_premios_mayores':main_check}
  (out/f'auditoria_acumulaciones_navidad_{year}_109.json').write_text(json.dumps(report,ensure_ascii=False,indent=2),encoding='utf-8')
  (out/f'premios_experimentales_navidad_{year}_109.json').write_text(json.dumps(detail,ensure_ascii=False,separators=(',',':')),encoding='utf-8')
  summary['anios'][y]={'premios_mayores_contrastados':13,'coincidencias_json_pdf_mas_reintegro':report['premios_mayores_pdf_mas_reintegro_coinciden_json'],'discrepancias':len(differences),'numeros_con_componentes':len(detail),'suma_experimental_euros':newtotal/100,'cambio_suma_euros':(newtotal-oldtotal)/100}
 (out/'informe_navidad_109.json').write_text(json.dumps(summary,ensure_ascii=False,indent=2),encoding='utf-8')
 print(json.dumps(summary,ensure_ascii=False,indent=2))
if __name__=='__main__':main()
